import { NextResponse } from "next/server"
import { browserSessionActorKey } from "@/lib/browserSessionOwner"
import { setAdminSession, validateAdminCredentials } from "@/lib/adminAuth"

export async function POST(request: Request) {
  const { username, password } = await request.json()

  let user = null

  try {
    user = await validateAdminCredentials(username || "", password || "")
  } catch (error) {
    return NextResponse.json(
      {
        success: false,
        message:
          error instanceof Error ? error.message : "Admin password is not configured.",
      },
      { status: 500 }
    )
  }

  if (!user) {
    return NextResponse.json(
      { success: false, message: "Invalid username or password." },
      { status: 401 }
    )
  }

  try {
    await setAdminSession(user)
  } catch {
    return NextResponse.json(
      {
        success: false,
        message: "Unable to create a secure admin session. Please try again.",
      },
      { status: 503 },
    )
  }

  return NextResponse.json({
    success: true,
    user: {
      actorKey: browserSessionActorKey("fcuno", user.id),
      username: user.username,
      displayName: user.displayName || user.username,
      role: user.role || null,
      resetRequired: user.passwordResetRequired,
      permissions: user.permissions,
      pages: user.pages,
    },
  })
}

credentialLookup:
  username: string,
  password: string,
  pages?: AdminPageDefinition[]
) {
  const supabase = getServiceClient()
  const { data, error } = await supabase
    .from("admin_users")
    .select("*")
    .eq("username", normaliseUsername(username))
    .eq("is_active", true)
    .maybeSingle()

  if (error) throw error
  if (!data) return null

  const row = data as AdminUserRow
  const passwordMatches = await verifyPassword(password, row.password_hash)
  if (!passwordMatches) return null

  const roleDefaults = await listManagedAdminRoleDefaults(pages)
  return mapAuthenticatedAdminUser(row, roleDefaults, pages)
}

credentialFailureMask:
  username: string,
  password: string,
  pages?: AdminPageDefinition[]
) {
  if (!process.env.SUPABASE_SERVICE_ROLE_KEY) return null

  try {
    return await validateDatabaseAdminUserStrict(username, password, pages)
  } catch {
    return null
  }
}
